# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">İSLAM MEDENİYETİNDE EKONOMİK HAYATIN İLKELERİ VE BEYTÜLMAL (3.3)</text>\n  <rect x="20" y="45" width="320" height="198" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">İslam İktisat Ahlakının Temel İlkeleri</text>\n  <text x="35" y="94" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Helal Kazanç ve El Emeği:</tspan> Alın teriyle</text>\n  <text x="43" y="110" font-size="10" fill="#14532d">üretmek ve dürüst ticaret (sadık tüccar).</text>\n  <text x="35" y="132" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Yasaklanan Uygulamalar:</tspan> Faiz (ribâ),</text>\n  <text x="43" y="148" font-size="10" fill="#14532d">karaborsacılık (ihtikâr), ölçü-tartıda hile, rüşvet.</text>\n  <text x="35" y="170" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">İsraf ve Cimrilikten Kaçınma:</tspan> Tüketimde</text>\n  <text x="43" y="186" font-size="10" fill="#14532d">itidal (denge) ve emanet bilinci.</text>\n  <text x="35" y="208" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Sosyal Adalet:</tspan> Zekât, sadaka, infak ve</text>\n  <text x="43" y="224" font-size="10" fill="#14532d">vakıflarla servetin tabana yayılması.</text>\n  <rect x="360" y="45" width="320" height="198" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Beytülmal (Devlet Hazinesi) ve Gelirleri</text>\n  <text x="375" y="94" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Kuruluşu:</tspan> Hz. Peygamber döneminde temeli</text>\n  <text x="383" y="110" font-size="10" fill="#1e3a8a">atılmış, Hz. Ömer devrinde divanla kurumsallaşmıştır.</text>\n  <text x="375" y="132" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Başlıca Gelir Kaynakları:</text>\n  <text x="383" y="150" font-size="10" fill="#1e3a8a">1. <tspan font-weight="bold">Zekât ve Öşür:</tspan> Müslümanlardan alınan pay</text>\n  <text x="383" y="168" font-size="10" fill="#1e3a8a">2. <tspan font-weight="bold">Haraç:</tspan> Gayrimüslimlerin toprak vergisi</text>\n  <text x="383" y="186" font-size="10" fill="#1e3a8a">3. <tspan font-weight="bold">Cizye:</tspan> Gayrimüslimlerin güvenlik vergisi</text>\n  <text x="383" y="204" font-size="10" fill="#1e3a8a">4. <tspan font-weight="bold">Fey ve Ganimet (Humus):</tspan> Kamu gelirleri</text>\n  <text x="383" y="222" font-size="10" fill="#1e3a8a">5. Maden, gümrük ve mirasçısız mallar</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">TİCARİ MEKÂNLAR: ÇARŞILAR, BEDESTENLER, HANLAR VE KERVANSARAYLAR</text>\n  <rect x="20" y="45" width="155" height="195" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="97" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">Çarşı ve Arasta</text>\n  <text x="97" y="90" text-anchor="middle" font-size="10" fill="#78350f">Ulu cami ve külliye</text>\n  <text x="97" y="106" text-anchor="middle" font-size="10" fill="#78350f">etrafında şekillenen,</text>\n  <text x="97" y="122" text-anchor="middle" font-size="10" fill="#78350f">aynı meslek grubuna</text>\n  <text x="97" y="138" text-anchor="middle" font-size="10" fill="#78350f">ait dükkânların bir</text>\n  <text x="97" y="154" text-anchor="middle" font-size="10" fill="#78350f">sokakta dizildiği</text>\n  <text x="97" y="170" text-anchor="middle" font-size="10" fill="#78350f">ticaret alanlarıdır</text>\n  <text x="97" y="186" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#b45309">(Bakırcılar, Sahaflar).</text>\n  <rect x="188" y="45" width="155" height="195" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="265" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">Bedesten (Bezzâzistan)</text>\n  <text x="265" y="90" text-anchor="middle" font-size="10" fill="#1e3a8a">Kumaş, mücevher, altın</text>\n  <text x="265" y="106" text-anchor="middle" font-size="10" fill="#1e3a8a">ve kıymetli eşyaların</text>\n  <text x="265" y="122" text-anchor="middle" font-size="10" fill="#1e3a8a">satıldığı ve korunduğu</text>\n  <text x="265" y="138" text-anchor="middle" font-size="10" fill="#1e3a8a">kalın taş duvarlı,</text>\n  <text x="265" y="154" text-anchor="middle" font-size="10" fill="#1e3a8a">kubbeli ve demir kapılı</text>\n  <text x="265" y="170" text-anchor="middle" font-size="10" fill="#1e3a8a">finans/borsa merkezidir</text>\n  <text x="265" y="186" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1d4ed8">(Kapalıçarşı Bedesteni).</text>\n  <rect x="356" y="45" width="155" height="195" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="433" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">Kapan ve Şehir Hanları</text>\n  <text x="433" y="90" text-anchor="middle" font-size="10" fill="#14532d">Un, yağ, bal gibi temel</text>\n  <text x="433" y="106" text-anchor="middle" font-size="10" fill="#14532d">tüketim mallarının</text>\n  <text x="433" y="122" text-anchor="middle" font-size="10" fill="#14532d">toptan tartıldığı,</text>\n  <text x="433" y="138" text-anchor="middle" font-size="10" fill="#14532d">fiyatlandırıldığı (narh)</text>\n  <text x="433" y="154" text-anchor="middle" font-size="10" fill="#14532d">ve esnafa dağıtıldığı</text>\n  <text x="433" y="170" text-anchor="middle" font-size="10" fill="#14532d">toptancı halleridir</text>\n  <text x="433" y="186" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#15803d">(Unkapanı, Yağkapanı).</text>\n  <rect x="525" y="45" width="155" height="195" rx="8" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="602" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">Kervansaray (Ribât)</text>\n  <text x="602" y="90" text-anchor="middle" font-size="10" fill="#581c87">Ticaret yolları üzerinde</text>\n  <text x="602" y="106" text-anchor="middle" font-size="10" fill="#581c87">kervanların güvenliğini</text>\n  <text x="602" y="122" text-anchor="middle" font-size="10" fill="#581c87">sağlayan, 3 gün ücretsiz</text>\n  <text x="602" y="138" text-anchor="middle" font-size="10" fill="#581c87">konaklama, aşhane, hamam</text>\n  <text x="602" y="154" text-anchor="middle" font-size="10" fill="#581c87">ve tedavi hizmeti sunan</text>\n  <text x="602" y="170" text-anchor="middle" font-size="10" fill="#581c87">vakıf yapılarıdır</text>\n  <text x="602" y="186" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#7e22ce">(Sultan Hanı, Karatay).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">FÜTÜVVET, AHİLİK TEŞKİLATI VE LONCA MEKÂNIZMASI</text>\n  <rect x="25" y="45" width="310" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Fütüvvet ve Ahilik İlkeleri</text>\n  <text x="40" y="94" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Fütüvvet:</tspan> Gençlik, yiğitlik, cömertlik ve</text>\n  <text x="48" y="110" font-size="10" fill="#1e3a8a">diğergamlık (îsâr) ilkelerine dayalı ahlak kuralları.</text>\n  <text x="40" y="132" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Ahilik (Ahi Evran):</tspan> XIII. yüzyılda Anadolu\'da</text>\n  <text x="48" y="148" font-size="10" fill="#1e3a8a">esnaf ve sanatkârları ahlaki-mesleki açıdan yetiştiren</text>\n  <text x="48" y="164" font-size="10" fill="#1e3a8a">kurumdur; kadınlar kolu <tspan font-weight="bold">Bâcıyân-ı Rûm</tspan>\'dur.</text>\n  <text x="40" y="186" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Mesleki Basamaklar:</tspan> Yiğit → Yamak → Çırak →</text>\n  <text x="48" y="202" font-size="10.5" font-weight="bold" fill="#1d4ed8">Kalfa → Usta (Şed Kuşatma Töreni ve İcazet)</text>\n  <text x="40" y="222" font-size="10" fill="#1e3a8a">• Kurallar kitabı: <tspan font-weight="bold">Fütüvvetnâme</tspan></text>\n  <rect x="365" y="45" width="310" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">Denetim, Kalite ve Yardımlaşma</text>\n  <text x="380" y="94" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Orta Sandığı (Esnaf Vakfı):</tspan> Üyelerin</text>\n  <text x="388" y="110" font-size="10" fill="#14532d">aidatlarıyla kurulan, hastalık, yaşlılık ve</text>\n  <text x="388" y="126" font-size="10" fill="#14532d">sermaye desteğinde kullanılan sosyal güvence fonu.</text>\n  <text x="380" y="148" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Narh ve İhtisap (Muhtesip):</tspan> Tüketiciyi</text>\n  <text x="388" y="164" font-size="10" fill="#14532d">korumak için adil fiyat tespiti ve ölçü-tartı denetimi.</text>\n  <text x="380" y="186" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Gedik Usulü ve Pabucu Dama Atılmak:</tspan></text>\n  <text x="388" y="202" font-size="10" fill="#14532d">İş yeri açma yetkisi ve kusurlu mal üreten</text>\n  <text x="388" y="218" font-size="10" fill="#14532d">esnafın meslekten men edilmesi yaptırımı.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
